+    .expect("before")
+    .path;
+    let after = model::toolpath_of(
+        &old,
+        &model::find_by_name(&old, "ZERO").expect("zero operation"),
+    )
+    .expect("after")
+    .path;
+    assert_eq!(
+        before, after,
+        "the v73 zero-radius path is byte/path identical"
