+#[test]
+fn minimum_radius_refuses_invalid_and_collapsed_offsets_by_name() {
+    for (value, word) in [
+        (-0.1, "non-negative"),
+        (f64::NAN, "finite"),
+        (f64::INFINITY, "finite"),
